  /** The signed-in reader; the avatar shows their initials. */
  account?: ProductShellAccount;
  /** The products the avatar menu switches between; the full menu and the lockup carry no product list. */
  products?: readonly ProductShellProduct[];
  notifications?: ProductShellNotifications;
  /** Ids of the pinned groups, items and children in the reader's order; the band shows the first six. */
  pinnedIds?: readonly string[];
  /** Pins or unpins an entry; without it the menu rows have no pin. */
  onPinnedChange?: (id: string, pinned: boolean) => void;
  /**
   * Takes the pins' new order, every id of `pinnedIds` in it, when the reader moves a pinned item
   * in the band: a drag that ends with it in a new place, or Alt+← / Alt+→ on it (TCRN-DS-SUB-149).
   * useProductShellController's productShellControlProps connect it to movePin, which keeps the
   * order in the pins preference (the product's backend through onPinsChange; never a cookie).
   * Without it the pinned items do not move.
   */
  onPinsReorder?: (orderedIds: readonly string[]) => void;
  /** Whether the full menu is open; the shell keeps its own state when omitted. */
  menuOpen?: boolean;
  /**
   * Whether ⌘K / Ctrl+K opens this shell's full menu: the key is registered on the document, once
   * per shell, so a page with several shells lets one of them have it and passes false to the
   * others. On by default (ShellMenu's `shortcut`; TCRN-DS-SUB-185).
   */
  menuShortcut?: boolean;
  onMenuOpenChange?: (open: boolean, reason: ProductShellMenuChangeReason) => void;
  /** The pinned item whose drop-down is open; the shell keeps its own state when omitted. */
  openPinId?: string | null;
  onOpenPinChange?: (id: string | null) => void;
  /** Whether the open full menu or pin drop-down takes focus. Defaults to true. */
  focusNavigationOnOpen?: boolean;
  /** The scroll frame that clips pin drop-down cascades, when the shell is embedded. */
  dropdownBoundaryRef?: RefObject<HTMLElement | null>;
  /**
   * Static states for documentation, by menu row or group id (data-tcrn-preview-state), passed to
   * the full menu and the drop-downs; a drop-down row marked "open" starts with its next level open.
   */
  previewStates?: Readonly<Record<string, string>>;
  /** Whether the avatar menu is open; the shell keeps its own state when omitted. */
  accountMenuOpen?: boolean;
  onAccountMenuOpenChange?: (open: boolean) => void;
  /** Placeholder of the full menu's search. */
  searchPlaceholder?: string;
  /** The full menu's search provider (whole-site targets); the menu model is searched when omitted. */
  searchProvider?: ShellMenuSearchProvider;
  onSearchQueryChange?: (query: string) => void;
  /**
   * A name for this shell, which tells its landmarks from another shell's on the same page (axe
   * landmark-unique): every named landmark of the shell — the band, the pinned items, the full menu
   * (panel or Sheet) and its bottom bar's trail, the drop-downs, the avatar menu and its product
   * switcher, the content region and the page header's trail — is named "{landmarkLabel} · {name}"
   * in the reader's language. A `contentLabel` or a page header's own `landmarkLabel` is used as it
   * is given. Omitted, they keep the built-in names (TCRN-DS-SUB-148, TCRN-DS-SUB-184).
